const LOTES=[{"codigo":"abreulima2024-tec","ano":2024,"orgao":"Prefeitura de Abreu e Lima","cargo":"Técnico em Enfermagem — edital 02/2024","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/tecnico-em-enfermagemcnm100-tipo-1_0.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/pref_abreuelima_gabarito_definitivo_da0a4fs131.pdf","questoes":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Observe a seguinte frase: “De todas as companhias para um escritor, nenhuma é mais valiosa do que um dicionário.” O dicionário é importante para o escritor, principalmente porque informa sobre","alternativas":["a correta grafia e significados dos vocábulos.","os vários significados de um vocábulo.","a origem de cada palavra.","a classificação de cada vocábulo.","a separação silábica das palavras"],"correta":"B"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"Observe a seguinte frase: “Enquanto viver o escritor, julgamos suas qualidades pela sua pior obra; uma vez morto, iremos julgá-lo pela sua obra mais perfeita”. Propomos abaixo uma série de modificações para segmentos dessa frase. Assinale a única modificação inadequada.","alternativas":["“Enquanto viver o escritor” = Durante a vida do escritor.","“julgamos suas qualidades” = suas qualidades são julgadas por nós.","“pela sua pior obra” = pela obra que não é a melhor.","“uma vez morto” = após sua morte.","“iremos julgá-lo” = vamos julgar o escritor"],"correta":"C"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Concordância Verbal e Nominal","enunciado":"Observe a seguinte frase em que ocorrem cinco erros gramaticais: “Confusa, epoca na qual os museus se converte em igreja, e as igrejas se convertem nos museus.” Assinale a correção inadequada, porque a forma da frase não está errada.","alternativas":["retirar a vírgula após “Confusa”.","“época” deve levar acento gráfico.","“na qual” deve ser substituído por “em que”.","“converte” deve ser substituído por “convertem”.","“igreja” deve ser substituído por “igrejas”"],"correta":"C"},{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Estrutura e Formação de Palavras","enunciado":"O sufixo -ada possui vários significados. Assinale a opção em que esse sufixo tem valor de “golpe, pancada”.","alternativas":["cachorrada, meninada.","pessegada, goiabada.","feijoada, bacalhoada.","bofetada, cadeirada.","caminhada, olhada"],"correta":"D"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Flexão Nominal e Verbal","enunciado":"As opções abaix o mostram um vocábulo e sua forma de plural correspondente. Assinale a opção em que a forma de plural está correta.","alternativas":["Cidadão / cidadões.","Corrimão / corrimães.","Testemunha-chave / testemunhas/chave.","Couve-flor / couve-flores.","Qualquer / quaisqueres"],"correta":"C"},{"numero":6,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"Assinale a frase abaixo em que a palavra “se” é uma conjunção.","alternativas":["Um relato é melhor se o fazem sem rodeios.","Uma ideia que não se põe em prática é um sonho.","Fazer-se algo impossível continua sendo impossível.","Pagarem-se mais impostos para quê?","Abraçaram-se calorosamente"],"correta":"A"},{"numero":7,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"Todas as opções abaixo mostram uma frase com repetição de termos. Assinale a opção em que essa repetição de termos foi evitada por meio do emprego de um hiperônimo (vocábulo genérico).","alternativas":["Uma anta foi capturada numa estação de trem. A anta conseguiu chegar à estação seguindo a via férrea. / Uma anta foi capturada numa estação de trem; o animal conseguiu chegar à estação seguindo a via férrea.","Minha avó foi ao oftalmologista por causa de seus problemas de visão. O oftalmologista indicou-lhe intervenção cirúrgica. / Minha avó foi ao oftalmologista por causa de seus problemas de visão e ele indicou-lhe intervenção cirúrgica.","O celeiro foi invadido po r ratos. Meus pais não conseguem acabar com esses ratos. / O celeiro foi invadido por ratos. Meus pais não conseguem acabar com esses principais roedores dos centros urbanos.","Meu professor indicou um livro de José de Alencar como leitura obrigatória. E u gosto dos livros de José de Alencar . / Meu professor indicou um livro de José de Alencar como leitura obrigatória. Eu gosto dos livros desse célebre autor de romances indianistas.","Pedro foi punido por simulação de falta na área. A simulação lhe rendeu a suspensão por um jogo. / Pedro foi punido por simulação de falta na área. O fingimento lhe rendeu a suspensão por um jogo"],"correta":"A"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"A maioria das palavras incluídas num dicionário têm seus significados indicados e acompanhadas de frases que exemplificam esses significados. Assinale a opção em que a frase exem plifica corretamente o significado.","alternativas":["CASA – local de moradia, residência: Cada botão tinha sua casa correspondente.","BURACO – cavidade: O carro caiu de repente num buraco da estrada.","CAMISA – tipo de vestimenta que cobre o tórax masculino: Colocaram o preso numa camisa de força.","TÊNIS – tipo de esporte de quadra: Os tênis importados estão custando os olhos da cara.","REMÉDIO – medicamento: A corrupção no Brasil parece não ter remédio. Raciocínio Lógico Matemático"],"correta":"B"},{"numero":11,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Na sequência abaixo, cada termo a partir do terceiro é obtido a partir dos dois termos anteriores usando -se uma mesma regra aritmética. 2, 3, 5, 8, 13, 21, ... O próximo termo dessa sequência é o","alternativas":["28.","30.","32.","34.","36"],"correta":"D"},{"numero":12,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"Se é verdade que nem todo x é y, avalie se as seguintes afirmativas são verdadeiras (V) ou falsas (F): I. Ao menos um x não é y. II. Algum y não é x. III. Todo y não é x. As afirmativas são, respectivamente,","alternativas":["V – V – V.","V – V – F.","V – F – F.","F – F – V.","F – F – F"],"correta":"B"},{"numero":13,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equações de 1º e 2º Grau","enunciado":"Daqui a 13 anos, Pedro terá a idade que Quincas tem hoje. Daqui a 23 anos, Quincas terá o dobro da idade atual de Pedro. O produto das idades atuais de Pedro e Quincas é igual a","alternativas":["946","1.402","1.764","1.820","1.938"],"correta":"C"},{"numero":14,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"Um anagrama de uma determinada palavra é uma reordenação qualquer de suas letras. Por exemplo, ROMA é um anagrama da palavra AMOR, MAOR é outro. A palavra AZUL tem a seguinte quantidade de anagramas:","alternativas":["16.","18.","20.","24.","32"],"correta":"D"},{"numero":15,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"Um torneio de voleibol será disputado por 10 equipes no sistema “mata-mata”, ou seja, em cada jogo, a equipe vencedora continua no torneio e a perdedora é eliminada. O número de jogos desse torneio será então igual a","alternativas":["9.","24.","30.","64.","90"],"correta":"A"},{"numero":16,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"Se não é verdade que João mora num apartamento e paga aluguel, então é verdade que","alternativas":["João mora numa casa.","João é proprietário do imóvel em que mora.","João mora numa casa da qual é proprietário.","João pode morar num apartamento.","João não mora num apartamento nem paga aluguel"],"correta":"D"},{"numero":17,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Conjuntos","enunciado":"Numa caixa há 4 bolas azuis, 5 bolas brancas e 5 bolas verdes, todas iguais em volume. Janete tem de retirar bolas às cegas da caixa, sem reposição, até ter certeza de que retirou ao menos uma de cada cor. A quantidade mínima de bolas que Janete tem de re tirar para ter essa certeza é igual a","alternativas":["4.","6.","8.","9.","11"],"correta":"E"},{"numero":18,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Aline, Beth, Carla, Denise e Elisa são amigas. Elisa é mais nova do que Beth e mais velha do que Carla. Denise é mais nova do que Carla. Aline é mais nova do que Beth. Elisa é mais nova do que Aline. Das cinco, a mais velha é","alternativas":["Aline.","Beth.","Carla.","Denise.","Elisa."],"correta":"B"},{"numero":19,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"Pedro saiu de casa, andou 50m por sua rua, em linha reta, até uma esquina, dobrou à esquerda, andou em linha reta por 120m, dobrou à direita numa rua perpendicular, andou 60m e chegou no mercado onde fez compras. Em seguida, Pedro andou mais 10m, no sentido em que chegou ao mercado, chegou à esquina, dobrou à esquerda numa perpendicular, andou 150m e chegou na casa de sua namorada Maria, de onde saiu 2 horas mais tarde. Pedro então voltou 20m no caminho por onde chegou à casa de Maria, dobrou à esquerda numa rua perpendicular, andou 140m por ela, dobrou à direita numa rua perpendicular e andou até chegar à sua rua. Nesse momento, Pedro estava então à seguinte distância, em metros, de sua casa:","alternativas":["20.","40.","60.","80.","120"],"correta":"A"},{"numero":21,"disciplina":"Direito Administrativo","assunto":"Agentes Públicos","enunciado":"Os requisitos básicos para investidura em cargo público incluem os seguintes, à exceção de um. Assinale-o.","alternativas":["A nacionalidade brasileira.","O gozo dos direitos políticos.","A quitação com as obrigações militares e eleitorais.","A idade mínima de 21 anos.","Aptidão física e mental"],"correta":"D"},{"numero":27,"disciplina":"Direito Administrativo","assunto":"Princípios da Administração Pública","enunciado":"Avalie se, de acordo com a Constituição Federal de 1988, a administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos seguintes princípios: I. legalidade II. impessoalidade III. moralidade IV. publicidade V. eficiência Estão corretos","alternativas":["I, II, III e IV, apenas.","II, III e V, apenas.","I, II, III, IV e V.","II, III, IV e V, apenas.","I, III e V, apenas"],"correta":"C"},{"numero":28,"disciplina":"Direito Administrativo","assunto":"Princípios da Administração Pública","enunciado":"De acordo com a Constituição Federal de 1 988, a administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá às seguintes disposições, à exceção de uma. Assinale-a.","alternativas":["Os cargos, empregos e funções públicas são acessíveis a os brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei.","A investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração.","O prazo de validade do concurso público será de até dois anos, prorrogável até três vezes, por igual período.","As funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei , destinam-se apenas às atribuições de direção, chefia e assessoramento.","É garantido ao servidor público civil o direito à livre associação sindical"],"correta":"C"},{"numero":29,"disciplina":"Direito Administrativo","assunto":"Responsabilidade Civil do Estado","enunciado":"Em relação à responsabilidade civil da Administração Pública, avalie se as afirmativas a seguir são falsas (F) ou verdadeiras (V): ( ) Decorre de ato omissivo ou comissivo, doloso ou culposo, que resulte em prejuízo ao erário ou a terceiros. ( ) Tratando-se de dano causado a terceiros, responderá o servidor perante a Fazenda Pública, em ação regressiva. ( ) A obrigação de reparar o dano não se estende -se aos sucessores. As afirmativas são, respectivamente,","alternativas":["V – V – V.","V – V – F.","F – F – F.","F – F – V.","V – F – V."],"correta":"B"},{"numero":30,"disciplina":"Direito Administrativo","assunto":"Improbidade Administrativa","enunciado":"As ações a seguir c onstituem ato de improbidade administrativa importando em enriquecimento ilícito, entre outras, à exceção de uma. Assinale-a.","alternativas":["Receber, para si ou para outrem, dinheiro, bem móvel ou imóvel, ou qualquer outra vantagem econômica, direta ou indireta, a t ítulo de comissão, percentagem, gratificação ou presente de quem tenha interesse, direto ou indireto, que possa ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público.","Receber vantagem econômica direta, de qualquer na tureza, para tolerar a exploração ou a prática de jogos de azar, de lenocínio, de narcotráfico, de contrabando, de usura ou de qualquer outra atividade ilícita, ou aceitar promessa de tal vantagem.","Perceber vantagem econômica, direta ou indireta, para facilitar a aquisição, permuta ou locação de bem móvel ou imóvel, ou a contratação de serviços por preço inferior ao valor de mercado.","Receber vantagem econômica indireta, de qualquer natureza, para tolerar a exploração ou a prática de jogos de azar, d e lenocínio, de narcotráfico, de contrabando, de usura ou de qualquer outra atividade ilícita, ou aceitar promessa de tal vantagem.","Aceitar emprego, comissão ou exercer atividade de consultoria ou assessoramento para pessoa física ou jurídica que tenha interesse suscetível de ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público, durante a atividade. Técnico em Enfermagem"],"correta":"C"},{"numero":31,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Acerca da evolução histórica do Sistema Único de Saúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O INAMPS prestava assistência médica prioritariamente aos trabalhadores que exerciam atividade remunerada e de forma secundária ao restante da população. ( ) A VIII Conferência Nacional de Saúde permitiu, pela primeira vez na história do país, a participação da sociedade civil organizada no processo de construção de um novo modelo de saúde. ( ) A Lei Eloi Chaves instituiu as Caixas de Aposentadoria e Pensão (CAP’s), sendo o marco inicial da previdência social no Brasil. As afirmativas são, respectivamente,","alternativas":["V – V – V.","F – V – V.","V – F – F.","F – V – F.","V – F– V"],"correta":"B"},{"numero":32,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Em 2024 a Lei no 8080/90 sofreu uma alteração com acréscimo de disposições acerca de um dos seus princípios. Essas disposições estão relacionadas","alternativas":["à capacidade de resolução dos serviços em todos os níveis de assistência.","à integração em nível executivo das ações de saúde, meio ambiente e saneamento básico.","à divulgação de informações quanto ao potencial dos serviços de saúde e a sua utilização pelo usuário.","à utilização da epidemiologia para o estabelecimento de prioridades na atenção básica.","ao acolhimento e atendimento a mulheres vítimas de qualquer tipo de violência"],"correta":"E"},{"numero":33,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"Com base nos níveis progressivos de assistência à saúde, assinale a opção que corresponde a um serviço da atenção terciária.","alternativas":["Ambulatório de neurologia.","Unidades de pronto atendimento.","Centros de atenção psicossocial.","Serviços de hemodinâmica.","Exames de ultrassonografia"],"correta":"D"},{"numero":35,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"Com base nos direitos dos usuários do SUS, analise as afirmativas a seguir: I. Todo cidadão tem liberdade de recusar ou permitir qualquer procedimento médico, assumindo a responsabilidade por isso. II. Nas situações de urgência/emergência, qualquer serviço de saúde deve receber e cuidar da pessoa, bem como encaminhá- la para outro serviço em caso de necessidade. III. Toda pessoa tem o direito de decidir se seus familiares e acompanhantes deverão ser informados sobre seu estado de saúde, exceto em casos de risco iminente de morte. Está correto o que se afirma em","alternativas":["I, II e III.","I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas"],"correta":"C"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"O Programa Cuida Mais Brasil foi instituído pela Portaria nº 937, de maio de 2022, e tem o propósito de aprimorar a assistência à saúde da mulher e saúde materno-infantil, no âmbito da atenção","alternativas":["primária.","secundária.","terciária.","psicossocial.","de alta complexidade"],"correta":"A"},{"numero":37,"disciplina":"Legislação do SUS","assunto":"Lei 8.142/1990","enunciado":"De acordo com a Lei nº 8.142/90, a representação dos usuários nos Conselhos e Conferências de Saúde deve ser paritária em relação ao conjunto dos demais segmentos. Isso significa que a soma dos representantes dos usuários de saúde deve","alternativas":["corresponder a 25% da composição total.","corresponder a 40% da composição total.","corresponder a 60% da composição total.","ser igual à soma dos representantes dos demais segmentos.","ser menor do que a soma dos representantes dos demais segmentos"],"correta":"D"},{"numero":38,"disciplina":"Enfermagem","assunto":"Atenção Primária à Saúde","enunciado":"Entre as atribuições específicas dos Técnicos de Enfermagem nas equipes de atenção básica está","alternativas":["realizar ações de atenção à saúde conforme a necessidade de saúde da população local.","realizar o cuidado da saúde da população adscrita, prioritariamente no âmbito da unidade de saúde.","manter atualizado o cadastramento das famílias no sistema de informação indicado pelo gestor municipal.","participar do processo d e territorialização e mapeamento da área de atuação da equipe.","participar do gerenciamento dos insumos necessários para o adequado funcionamento da UBS"],"correta":"E"},{"numero":39,"disciplina":"Legislação do SUS","assunto":"Direitos dos Usuários do SUS","enunciado":"Assegurar o cumprimento dos direitos dos usuários do SUS em todas as fases do cuidado faz parte do seguinte aspecto da Política Nacional de Humanização:","alternativas":["Metas.","Objetivos.","Diretrizes.","Princípios.","Valores"],"correta":"C"},{"numero":40,"disciplina":"Legislação do SUS","assunto":"Decreto 7.508/2011","enunciado":"Com base nas disposições do Decreto nº 7.508/11, analise as afirmativas a seguir e assi nale (V) para a verdadeira e (F) para a falsa. ( ) O processo de planejamento da saúde deve ser ascendente e integrado, do nível local até o federal. ( ) Os serviços de atenção hospitalar e os ambulatoriais especializados devem ser referenciados pelas Redes de Atenção à Saúde. ( ) O acesso universal e igualitário às ações e aos serviços de saúde deve ser ordenado pela atenção primária. As afirmativas são, respectivamente,","alternativas":["F – F – F.","V – F – V.","F – V – F.","V – V – V.","F – V – V"],"correta":"B"},{"numero":41,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"Com base no protocolo de identificação do paciente do Ministério da Saúde, analise as afirmativas a seguir e assinale V para a verdadeira e F para a falsa. ( ) Pulseiras coloridas de alerta ou etiquetas podem ser utilizadas como identificadoras do paciente, caso não tenha pulseiras brancas na instituição. ( ) Recomenda-se utilizar no mínimo 3 identificadores como nome completo do paciente, nome completo da mãe do paciente e data de nascimento do paciente. ( ) O registro dos id entificadores do paciente podem ser impressos de forma digital ou podem ser manuscritos. As afirmativas são, respectivamente,","alternativas":["F – F – V.","V – F – V.","F – V – F.","V – V – V.","F – F – F"],"correta":"A"},{"numero":42,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Considere um mapa de risco para am bientes com as seguintes características: consultório 1, com um círculo marrom visível, consultório 2, com um círculo amarelo visível, e sala de procedimentos, com um círculo verde visível. Nesse caso, os riscos representados nesses ambientes são, respectivamente,","alternativas":["físico, químico e biológico.","biológico, ergonômico e físico.","ergonômico, biológico e físico.","químico, biológico e ergonômico.","mecânico, biológico e ergonômico."],"correta":"B"},{"numero":43,"disciplina":"Enfermagem","assunto":"Centro Cirúrgico","enunciado":"O equipamento cirúrgico que possibilita a realização de imagens intraoperatórias dinâmicas, de alta resolução e em tempo real é denominado","alternativas":["eletrocautério.","negatoscópio.","foco cirúrgico.","arco cirúrgico.","arco de narcose"],"correta":"D"},{"numero":44,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"Acerca do processamento de produtos para a saúde é correto afirmar que","alternativas":["a desinfecção química do CME deve ser realizada preferencialmente em sala exclusiva, podendo também ser realizada no ambiente de limpeza.","o uso de caixas metálicas sem furo s para esterilização de materiais deve ser realizado somente em situações de emergência.","produtos para saúde classificados como semicríticos devem ser submetidos, no mínimo, ao processo de desinfecção de nível intermediário, após a limpeza.","para produtos cujo lúmen tenha diâmetro interno inferior a 5 milímetros é obrigatório que a fase automatizada da limpeza seja feita em lavadora ultrassônica com conector para canulados.","o rótulo de identificação das embalagens dos produtos para saúde submetid os à esterilização deve conter, no mínimo, nome do produto, número do lote e data da esterilização"],"correta":"D"},{"numero":45,"disciplina":"Enfermagem","assunto":"Centro Cirúrgico","enunciado":"De acordo com o Protocolo de Cirurgia Segura, antes de o paciente sair da sala de cirurgia, a equipe deverá revisar em conjunto a cirurgia realizada por meio de alguns passos. Um desses passos diz respeito ao seguinte aspecto:","alternativas":["nova profilaxia antimicrobiana.","nível de consciência do paciente.","monitoramento adequado do paciente.","nível de perda sanguínea durante a cirurgia.","identificação de qualquer amostra cirúrgica obtida"],"correta":"E"},{"numero":46,"disciplina":"Enfermagem","assunto":"Centro Cirúrgico","enunciado":"Com base na divisão das áreas do Centro Cirúrgico, a sala de guarda de equipamentos e os vestiários são classificados respectivamente como áreas","alternativas":["restrita e irrestrita.","irrestrita e semirrestrita.","semirrestrita e irrestrita.","restrita e semirrestrita.","semirrestrita e restrita"],"correta":"C"},{"numero":47,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"De acordo com as recomendações da ANVISA, se houver necessidade de retirar os pelos para um procedimento cirúrgico deve-se fazê-lo imediatamente antes da cirurgia. Com base nas recomendações da ANVISA acerca da tricotomia pré-operatória, nos procedimentos cirúrgicos de abdome superior deve-se retirar os pelos desde","alternativas":["a linha dos mamilos até acima do púbis.","o pescoço até abaixo do umbigo.","o ombro até a parte superior da coxa.","acima do umbigo até a parte superior das coxas.","a linha axilar inferior até abaixo do umbigo"],"correta":"A"},{"numero":48,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"De acordo com as recomendações da ANVISA para prevenção de infecção relacionada à assistência à saúde, o sistema fechado de aspiração deve ser trocado sempre que houver sujidade ou mau funcionamento ou a cada","alternativas":["24 horas.","36 horas.","48 horas.","72 horas.","96 horas"],"correta":"D"},{"numero":49,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Ao verificar a frequência respiratória de um paciente adulto, o profissional de enfermagem identificou a presença de bradpneia. Essa condição é caracterizada por uma frequência respiratória menor do que","alternativas":["12 respirações/minuto.","14 respirações/minuto.","15 respirações/minuto.","18 respirações/minuto.","20 respirações/minuto"],"correta":"A"},{"numero":50,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"A elevação anormal da temperatura, com risco de morte, que ocorre quando pessoas suscetíveis recebem certos medicamentos anestésicos é denominada hipertermia","alternativas":["séptica.","maligna.","clássica.","contínua.","ondulante"],"correta":"B"},{"numero":51,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Com base nas disposições acerca da segurança no trabalho, analise as afirmativas a seguir e assinale V para a verdadeira e F para a falsa. ( ) Entre as medidas preventivas relacionadas à ergonomia no trabalho estão as pausas para propiciar a recuperação psicofisiológica dos trabalhadores, que devem ser computadas como tempo de trabalho efetivo. ( ) Em casos excepcionais e que envolvem um maior risco de contaminação, o uso de luvas estéreis pode substituir o processo de lavagem das mãos. ( ) Os quartos ou enfermarias destinados ao isolamento de pacientes portadores de doenças infectocontagiosas devem conter lavatório em seu interior. As afirmativas são, respectivamente,","alternativas":["V – V – F.","V – V – V.","F – F – F.","V – F – V.","F – V – F."],"correta":"D"},{"numero":52,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Ao realizar o curativo em um paciente, o profissional de enfermagem observou a presença de esfacelo. Acerca desse achado é correto afirmar que","alternativas":["tem coloração rósea ou avermelhada é de extrema importância no processo de cicatrização aparentemente brilhante e úmido é rico em colágeno.","aparece na ferida como um novo tecido róseo e brilhante (pele), desenvolve-se a partir das bordas favorecendo o fecha mento da ferida.","é caracterizado por borda esbranquiçada que ocorre devido ao excesso de umidade na ferida e pelo aumento da exsudação.","é resultante da morte celular e tecidual e com consequência perda da função orgânica e do metabolismo e de forma irreversível.","é um tecido inviável, formado por uma membrana fibrosa, composta pelo conjunto de c élulas mortas acumuladas no exsudato"],"correta":"E"},{"numero":53,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"O teste da orelhinha (triagem auditiva neonatal) é um exame que faz parte da triagem neonatal e deve ser feito ainda na maternidade, preferencialmente, entre","alternativas":["06 e 12h de vida.","12 e 24h de vida.","24 e 48h de vida.","48 e 72h de vida.","72 e 96h de vida"],"correta":"C"},{"numero":54,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Um dos cuidados que o profissional de enfermagem precisa ter durante a administração de medicamentos é em relação às possíveis interações medicamentosas. Nesse sentido, a administração simultânea de insulina e captopril pode","alternativas":["causar uma hipotensão severa.","diminuir o efeito anti-hipertensivo do captopril.","aumentar o efeito hipoglicemiante da insulina.","diminuir o efeito hipoglicemiante da insulina.","aumentar o efeito anti-hipertensivo do captopril"],"correta":"C"},{"numero":55,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Acerca da administração de medicamentos, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Na infusão rápida, o medicamento deve ser administrado em até 10 minutos, não podendo ultrapassar esse tempo. ( ) A penicilina crist alina e a penicilina procaína devem ser administradas exclusivamente pela via endovenosa, em até 30 minutos. ( ) O diazepam, quando administrado pela via endovenosa, deve ser diluído em 10mL de água destilada e administrado de forma lenta. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – F – V.","F – V – V.","V – V – V.","F – F – F"],"correta":"E"},{"numero":56,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"De acordo com as diretrizes da American Heart Association, na assistência pós-PCR de um paciente adulto, recomenda-se manter uma temperatura corporal entre","alternativas":["31°C e 35°C.","32°C e 36°C.","32°C e 37,5°C.","33°C e 35,5°C.","33°C e 36,5°C"],"correta":"C"},{"numero":57,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Na assistência a um paciente adulto em parada cardiorrespiratória e com via aérea avançada, deve-se administrar","alternativas":["seis ventilações/min.","dez ventilações/min.","doze ventilações/min.","uma ventilação a cada 8 segundos.","uma ventilação a cada 10 segundos"],"correta":"B"},{"numero":58,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Assinale a opção que apresenta uma característica de uma queimadura de primeiro grau.","alternativas":["Todas as camadas teciduais são atingidas, incluindo fáscia, músculos e osso em alguns casos.","Pele de aspecto variável, principalmente em sua coloração (pálida a preta), inelástica, ressecada e endurecida ao toque.","Atinge totalmente a epiderme e a derme de maneira variável e ocorre regeneração espontânea.","Pele de aspecto bolhoso, hiperemiada, edemaciada, dolorosa, com erosão ou ulceração.","Pele de aspecto seco, hiperemiada, dolorosa e sem formação de bolhas"],"correta":"E"},{"numero":59,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Na assistência a uma vítima de afogamento é importante identificar algumas características específicas a fim de prestar o socorro adequado. Na avaliação da gravidade, faz parte dos sinais e sintomas apresentados por uma pessoa com afogamento Grau 3:","alternativas":["parada cardiorrespiratória.","tosse, sem espuma na boca/nariz.","muita espuma na boca/nariz sem pulso radial palpável.","muita espuma na boca/nariz com pulso radial palpável.","parada respiratória, com pulso carotídeo ou sinais de circulação presentes"],"correta":"D"},{"numero":60,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"De acordo com as orientações do Ministério da Saúde, a Vacina Varicela (atenuada) é contraindicada para crianças","alternativas":["maiores de 4 anos de idade.","menores de 2 anos de idade.","maiores de 7 anos de idade.","menores de 9 meses de idade.","menores de 12 meses de idade."],"correta":"D"},{"numero":61,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Acerca dos acidentes de trabalho com exposição a material biológico, analise as afirmativas a seguir e assinale V para a verdadeira e F para a falsa. ( ) Suor, secreções nasais e urina são considerados materiais biológicos sem risco de transmissão do HIV, exceto se houver presença de sangue. ( ) Lesões causadas por agulhas ou outros instrumentos perfurantes são classificadas como exposição percutânea. ( ) Após exposição ocupacional a material biológico, o profissional de saúde deve iniciar a profilaxia de hepatite B, independente da sua situação vacinal. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – F.","F – F – V.","V – V – V"],"correta":"C"},{"numero":62,"disciplina":"Enfermagem","assunto":"Diabetes Mellitus","enunciado":"Durante a assistência a um paciente com diabetes mellitus tipo 1 (DM1), o profissional de enfermagem identificou alguns sinais e sintomas característicos de cetoacidose diabética. Um desses sinais é a","alternativas":["febre.","letargia.","cefaleia.","mialgia.","hipertensão"],"correta":"B"},{"numero":63,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Na definição da Hipertensão Gestacional, é necessário, entre outros critérios, medir a pressão arterial em duas ocasiões com, pelo menos,","alternativas":["uma hora de intervalo.","duas horas de intervalo.","três horas de intervalo.","quatro horas de intervalo.","cinco horas de intervalo"],"correta":"D"},{"numero":64,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"O dispositivo de oxigenoterapia mais indicado em situações nas quais o paciente necessita de um controle mais exato da FiO2 é","alternativas":["cânula nasal.","cateter nasal.","máscara simples.","máscara de Venturi.","máscara não reinalante"],"correta":"D"},{"numero":65,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"O seguinte medicamento deve ser protegido da exposição excessiva da luz solar ou de lâmpadas artificiais:","alternativas":["dopamina.","aminofilina.","ampicilina.","dexametasona.","diclofenaco de sódio"],"correta":"A"},{"numero":66,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"De acordo com as ori entações do Ministério da Saúde, uma condição materna que contraindica a amamentação é a(o)","alternativas":["infecção por dengue.","uso de radiofármacos.","infecção por hepatite B.","tratamento com antibiótico.","infecção por tuberculose"],"correta":"B"},{"numero":67,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"Uma equipe de saúde realizou um trabalho de busca ativa de sintomáticos respiratórios em sua área de abrangência. São incluídos nesse grupo pessoas com tosse por período","alternativas":["≥ 5 dias de duração.","≥ 7 dias de duração.","≥ 10 dias de duração.","≥ 2 semanas de duração.","≥ 3 semanas de duração"],"correta":"E"},{"numero":68,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Acerca das ações do Ministério da Saúde voltadas para a saúde do homem, analise as afirmativas a seguir e assinale V para a afirmativa verdadeira e F para a falsa. ( ) Uma das estratégias da Política Nacional de Atenção Integral à Saúde do Homem (PNAISH) é a realização do Pré -Natal do Parceiro que tem entre seus objetivos envolver o homem nas etapas de gestação, parto, pós-parto e cuidados com o bebê. ( ) Entre as ações de promoção da saúde do homem está a busca ativa de homens na comunidade, orientando -os sobre a importância e a necessidade dos cuidados com a saúde. ( ) Um dos eixos prioritários da Política Nacional de Atenção Integral à Saúde do Homem visa a conscientização sobre a relação significativa entre a população masculina e violências e acidentes. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – V.","F – F – F.","V – V – F"],"correta":"C"},{"numero":69,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"A notificação compulsória relacionada a aciden tes com ferroada de escorpião marrom, deve ser realizada em até","alternativas":["12 horas.","24 horas.","48 horas.","7 dias.","15 dias."],"correta":"B"},{"numero":70,"disciplina":"Legislação do COFEN","assunto":"Código de Ética dos Profissionais de Enfermagem","enunciado":"Com base nas disposições acerca do Código de Ética de Enfermagem, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O profissional de enfermagem tem o dever de prestar assistência de Enfermagem sem discriminação de qualquer natureza. ( ) Nas penalidades de suspensão e cassação, o profissional terá sua carteira r etida no ato da notificação, em todas as categorias em que for inscrito. ( ) As penalidades referentes à censura e cassação são de competência do Conselho Federal de Enfermagem. As afirmativas são, respectivamente,","alternativas":["V – V – F.","F – V – F.","V – F – V.","V – V – V.","F – F – F."],"correta":"A"}]},{"codigo":"abreulima2024-enf-complemento","ano":2024,"orgao":"Prefeitura de Abreu e Lima","cargo":"Enfermeiro — questões 1–20, edital 02/2024","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/enfermeirocns201-tipo-1_0.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/pref_abreuelima_gabarito_definitivo_da0a4fs131.pdf","questoes":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"Os adjetivos podem ser empregados com gradação, nos graus comparativo e superlativo. Assinale a frase que se mostra no grau comparativo.","alternativas":["O presidente é mais falante que atuante.","O ministro é o mais simpático do grupo.","Os batedores de carteira são rapidíssimos.","Todos os alunos são muito inteligentes.","Nem todos os secretários são bastante cultos"],"correta":"A"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Observe o seguinte texto descritivo: “O pessegueiro estava alto, mas suas folhas mostravam uma coloração amarelada, que parecia problemática; os galhos estavam cobertos de uma espécie de farinha branca e os poucos frutos ainda estavam pequenos”. Sobre esse pequeno texto, assinale a afirmativa correta.","alternativas":["Texto de conteúdo concreto acumulativo, o que dificulta a apreensão de uma unidade global.","Texto de conteúdo abstrato, com justaposição de ideias para a construção da ideia global do objeto descrito.","Texto cujo observador segue uma estratégia de movimento de longe para perto.","Texto em que predomina a inform ação de fatos, situações e acontecimentos.","Texto cujos segmentos mostram relação lógica de causa e efeito, mostrando sequência cronológica"],"correta":"A"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"As frases abaixo falam de um aspecto da arte de escrever. Assinale a opção em que esse aspe cto não está corretamente identificado.","alternativas":["O mais importante não é o número de ideias agrupadas em seu texto, mas o vínculo que as une / as relações de coesão e coerência entre as partes do texto.","O que é bem-dito, diz-se com rapidez / a concisão text ual, ou seja, utilização somente dos elementos textuais necessários.","Devemos falar como nos testamentos: quanto menos palavras, menos questões / o texto deve ser construído com verdades e não com a imaginação.","A chave para a criatividade é fazer co nexões inusitadas / um texto criativo é o que busca a originalidade.","Palavras são uma barreira à comunicação / as palavras não conseguem expressar o conteúdo individual do enunciador"],"correta":"C"},{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"Assinale a frase abaixo em que o vocábulo melhor mostra uma classe gramatical diferente das demais.","alternativas":["Dinheiro é o melhor cosmético.","A melhor forma de emagrecer é ser mãe em tempo integral.","Se há alguma coisa que queremos mudar em uma criança, devemos primeiro verificar se não é melhor fazer essa mudança em nós mesmos.","Não há melhor amigo nem parente do que nós mesmos.","As aulas presenciais ensinam melhor que as aulas à distância"],"correta":"E"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Sintaxe da Oração e do Período","enunciado":"Entre as frases abaixo, assinale aquela em que a substituição proposta é adequada, por tratar -se do único caso de adjunto adnominal.","alternativas":["Poetas são engarrafadores de nuvens (nebulosos).","A arte, mesmo a mais pessimista, é uma proposição de felicidade (feliz).","Como faço uma escultura? Simp lesmente retiro do bloco de mármore (marmóreo) tudo o que não é necessário.","A necessidade de dinheiro (monetária) traz grandes dificuldades às famílias pobres.","A arte é a busca do dispensável (inútil)"],"correta":"C"},{"numero":8,"disciplina":"Língua Portuguesa","assunto":"Ortografia e Acentuação","enunciado":"Nas abreviaturas comuns há uma série de princípios que são seguidos no uso. Assinale a opção abaixo em que o exemplo dado corresponde ao princípio colocado anteriormente.","alternativas":["A ordem das letras do vocábulo deve ser obedecida: general / gal.","Por motivo de clareza, devem -se incluir na abreviatura todas as consoantes finais na parte abreviada: superfície / super.","O plural de uma abreviatura é feito com a repetição dessa letra: páginas / pp.","As abreviaturas mantêm os acentos das palavras originais: árabe / ar.","Uma abreviatura não deve terminar em vogal: Vossa Excelência / V. Exa."],"correta":"C"},{"numero":9,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"Assinale a frase abaixo que não exemplifica a substantivação de um adjetivo.","alternativas":["O permitido não me agrada; o proibido excita o meu desejo.","Para conseguir o maravilhoso, faça o impensável.","A sorte nem sempre favorece os mais dignos.","Não há solidão mais solitária do que a desconfiança.","O arranhado da mesa foi causado pela transportadora"],"correta":"D"},{"numero":11,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Numa aula de raciocínio lógico o professor afirma que tem um gato, um cachorro e um papagaio. Ele propõe à turma o seguinte desafio. “Um dos animais se chama Farinha, ou outro, Farofa, e o terceiro, Farelo. Considerem que, das três afirmações I, II e III, a seguir, apenas uma é verdadeira: I. Farinha é o gato. II. Farofa não é o gato. III. Farelo não é o cachorro. Identifiquem os nomes do gato, do cachorro e do papagaio.” Flávia, a aluna mais esperta, respondeu corretamente que Farinha, Farofa e Farelo são, respectivamente, os nomes","alternativas":["do gato, do cachorro e do papagaio.","do cachorro, do gato e do papagaio.","do gato, do papagaio e do cachorro.","do papagaio, do gato e do cachorro.","do cachorro, do papagaio e do gato"],"correta":"B"},{"numero":12,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Conjuntos","enunciado":"Uma urna contém 5 bolas azuis, 6 bolas brancas, 7 bolas verdes e 7 bolas pretas. O número mínimo de bolas que devem ser retiradas, às cegas, para que se possa garantir que, entre as bolas retiradas, há ao menos uma de cada cor é igual a","alternativas":["17.","18.","19.","20.","21"],"correta":"E"},{"numero":13,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"No jogo de basquetebol, cada cesta conseguida pode valer 1, 2 ou 3 pontos para a equipe que marcou a cesta. Ganha a partida a equipe que consegue mais pontos. Em uma determinada partida, Jorge “M ão de Ouro” fez 17 cestas e anotou, no total, 36 pontos. Sabe -se, ainda que o número de cestas de 2 pontos que Jorge marcou foi o triplo do número de cestas de 1 ponto que ele conseguiu. Se x é o número de cestas de 1 ponto, y é o número de cestas de 2 pontos e z, o de cestas de 3 pontos conseguidos por Jorge, então o produto xyz é igual","alternativas":["108.","120.","134.","135.","180"],"correta":"D"},{"numero":14,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"Em uma família composta por dez pessoas, seis torcem para o Vainafé F.C. e quatro torcem para o Contrarolo F.C. A família ganhou quatro ingressos para o próximo jogo da seleção brasileira e vai escolher dois torcedores do Vainafé e dois do Contrarolo para irem ao referido jogo. O número de diferentes possibilidades de se escolher os quatro membros é igual a","alternativas":["18.","24.","48.","60.","90"],"correta":"E"},{"numero":15,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"Se nem todo A é B, mas todo B é C, avalie se é verdade que I. Nem todo C é B. II. Pode ser que todo A seja C. III. Todo B é A. Está correto o que se afirma em","alternativas":["II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"A"},{"numero":16,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equações de 1º e 2º Grau","enunciado":"Daqui a 16 anos, João terá a idade que Fábio tem hoje. Daqui a 32 anos, Fábio terá o dobro da idade atual de João. Se dividirmos a idade atual de João pela idade atual de Fábio obtemos","alternativas":["0,50.","0,66.","0,75.","0,80.","0,82."],"correta":"C"},{"numero":17,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Na sequência a seguir, cada termo a partir do terceiro é obtido a partir dos dois termos anteriores com base em uma mesma regra aritmética. 3, 4, 7, 11, 18, 29, ... Assim, o décimo quinto termo dessa sequência é igual a","alternativas":["1364.","1876.","2207.","3571.","6778"],"correta":"C"},{"numero":18,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"Uma ‘capicua’ é um número que lido de trás para a frente é igual ao número original. Por exemplo, 121 e 234432 são ‘capicuas’. O número de ‘capicuas’ de quatro algarismos que podem ser formados usando-se os algarismos 0, 1, 2, 3, 4 e 5 é igual a","alternativas":["16.","30.","48.","60.","90"],"correta":"B"},{"numero":19,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"A negação de “Se x > 0 então y > 3” é","alternativas":["x ≤ 0 e y ≤ 3.","x > 0 e y ≤ 3.","x > 0 ou y > 3.","y ≤ 3.","x ≤ 0 ou y ≤ 3"],"correta":"B"}]},{"codigo":"canaa2025-epi","ano":2025,"orgao":"Prefeitura de Canaã dos Carajás","cargo":"Agente de Serviços de Vigilância Epidemiológica","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/agente-de-servicos-de-vigilancia-epidemiologicacnm106-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/prefcanaa202403_gabarito_definitivo-compilado-06.04_0.pdf","questoes":[{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Funções da Linguagem","enunciado":"Assinale a opção que apresenta a frase que é vista como injuntiva, por mostrar ordem ou conselho.","alternativas":["Os animais não suportam a prisão.","É cruel manter um animal trancado.","Os animais vivem livres na natureza.","Não prenda seu cachorro no apartamento.","Os bichos precisam de carinho, como nós"],"correta":"D"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"Todas as frases a seguir estão na voz passiva à exceção de uma. Assinale a única que se mostra na voz ativa.","alternativas":["Comprou-se um móvel novo para a sala.","O presidente da República foi eleito pelo povo.","Muitos alunos foram repreendidos pelo diretor.","Todos foram selecionados pelo diretor da empresa.","Elegeram os deputados em rápido processo eletivo"],"correta":"E"},{"numero":6,"disciplina":"Língua Portuguesa","assunto":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Em todas as frases a seguir encontram -se perífrases bem conhecidas. Assinale a opção que apresenta a frase em que essa perífrase está erradamente identificada.","alternativas":["O rei dos animais permaneceu dormindo por horas. / o leão.","De raça pura ou não, esse animal é o melhor amigo do homem. / o cachorro.","Todos os anos são homenageados os que participam da sétima arte. / o cinema.","João estava cansado e, em pouco tempo, estava nos braços de Morfeu. / divertindo-se.","Duas vezes menor do que a Terra, o planeta vermelho atrai a curiosidade dos cientistas. / Marte"],"correta":"D"},{"numero":7,"disciplina":"Língua Portuguesa","assunto":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Assinale a opção em que o motivo da comparação está identificado corretamente.","alternativas":["Os olhos dela pareciam dois faróis / colorido.","O tecido é como uma carícia no corpo / massagem.","A mão de meu pai parece feita de pedra / tamanho.","Há um inseto no meu quarto que parece um morcego / feiura.","Os adultos procediam como crianças no Natal / a tranquilidade"],"correta":"D"},{"numero":8,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Todas as frases abaixo foram construídas com o verbo fazer, que foi substituído por outro de sentido mais específico. Assinale a frase em que essa substituição foi feita corretamente.","alternativas":["Diante do público, os atletas fizeram uma demonstração de sua velocidade / comprovaram.","No meio da semana, a cozinheira fez um prato que surpreendeu nossos convidados / elaborou.","As mães fizeram as fantasias para o desfile / costuraram.","Os alunos fizeram os exercícios físicos com rapidez / responderam aos exercícios.","Uma vez feito o trabalho, fomos ao cinema / praticado"],"correta":"B"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Estrutura e Formação de Palavras","enunciado":"As opções a seguir mostram três vocábulos da mesma família, exceto uma, em que há um termo intruso. Assinale-a.","alternativas":["Lua / lunar / lunático.","Paz / pacífico / paciente.","Astro / asteroide / astral.","Terra / terreno / desterrar.","Hipódromo / hípica / hipismo. Raciocínio Lógico Matemático"],"correta":"B"},{"numero":11,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Na sala em que Sílvio trabalha, havia, no início do mês, 30 copos descartáveis. No 1º dia do mês, ele usou apenas 1 copo descartável. No 2º dia do mês, ele usou apenas 2 copos descartáveis daqueles que restaram. No 3º dia do mês, ele usou apenas 3 copos descartáveis daqueles que restaram. Assim, Sílvio manteve o padrão de consumo de copos descartáveis usando, a cada dia, um copo descartável a mais do que no dia anterior. Entretanto, chegou um dia em que Sílvio não pôde mais manter esse padrão porque não ha via copos suficientes. Ele então usou todos os que havia restado. Nesse último dia, Sílvio usou apenas","alternativas":["1 copo.","2 copos.","3 copos.","4 copos.","5 copos"],"correta":"B"},{"numero":12,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Conjuntos","enunciado":"Dentro de uma caixa, há 6 balas de hortelã e 4 balas de leite. Se 5 dessas balas forem retiradas da caixa, é certo que","alternativas":["4 delas serão de leite.","todas serão de hortelã.","3 serão de hortelã e 2 de leite.","pelo menos uma delas será de leite.","pelo menos uma delas será de hortelã"],"correta":"E"},{"numero":13,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"O responsável pelo almoxarifado de uma r epartição pública precisa providenciar a compra de 20 embalagens de papel A4, 15 caixas de caneta esferográfica e 10 cartuchos de tinta para impressora. No seu fornecedor, cada embalagem de papel A4 custa R$ 8,90. Cada caixa de caneta esferográfica custa R $ 4,90. Cada cartucho de tinta para impressora custa R$ 74,90. O fornecedor oferece 6% de desconto sobre o valor total da compra. Para suprir a demanda do almoxarifado, serão necessários","alternativas":["R$ 980,49.","R$ 960,48.","R$ 940,47.","R$ 920,46.","R$ 900,45"],"correta":"C"},{"numero":14,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equações de 1º e 2º Grau","enunciado":"Claudinei tem um porta -níqueis onde há apenas moedas de 1 centavo. Em uma segunda -feira, ele retirou do porta -níqueis a metade dessas moedas. No dia seguinte, ele retirou a metade do que sobrou dentro do porta -níqueis depois da 1ª retirada. Na quarta- feira, ele retirou a metade do que sobrou dentro do porta-níqueis depois da 2ª retirada. Assim continuou, diariamente, retirando a metade do que sobrou após a retirada feita no dia anterior. Na sexta-feira, após a retirada do dia, sobraram no por ta-níqueis exatos 3 centavos. É correto afirmar que, na segunda -feira, antes da primeira retirada, havia no porta-níqueis","alternativas":["mais de R$ 1,00.","exatamente R$ 1,00.","mais de R$ 0,50 e menos de R$ 1,00.","exatamente R$ 0,50.","menos de R$ 0,50"],"correta":"C"},{"numero":15,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"A cada mês trabalhado na empresa X, Gabriel acumulou em seu Fundo de Garantia o equivalente a 1/12 do seu salário mensal. No momento do seu desligamento dessa empresa, o total acumulado no fundo proveniente da empresa X era de 5,5 salários mensais. É correto concluir que Gabriel trabalhou na empresa X por","alternativas":["5 anos e 5 meses.","5 anos e 6 meses.","5 anos e 7 meses.","6 anos e 5 meses.","6 anos e 6 meses"],"correta":"B"},{"numero":16,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"Considere verdadeira a seguinte declaração: “Se eu acordo tarde, não faço desjejum.” É correto concluir que","alternativas":["se eu não acordo tarde, faço desjejum.","se eu não acordo tarde, também não faço desjejum.","se eu faço o desjejum, então acordei tarde.","se eu faço o desjejum, então não acordei tarde.","se eu não faço o desjejum, então acordei tarde"],"correta":"D"},{"numero":17,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Estatística Descritiva","enunciado":"Seja A um conjunto de dados composto por 5 valores numéricos. A média dos três menores valores é 5. A média dos dois maiores é 10,5. É correto concluir que a média dos valores do conjunto A vale","alternativas":["7,2.","7,0.","6,4.","5,8.","5,5."],"correta":"A"},{"numero":18,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Geometria Analítica","enunciado":"Os pontos A(2,0) e B(0,2), identificados no sistema de coordenadas cartesianas, são vértices consecutivos do quadrado ABCD. Se os demais vértices desse quadrado estão no 1º quadrante, um desses vértices pode ser identificado como um ponto de coordenadas","alternativas":["(2,2).","(4,4).","(4,0).","(2,4).","(0,4)"],"correta":"D"},{"numero":19,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"Em uma eleição em que concorrem apenas 2 candidatos, 45% do total de votos foram dados ao candidato vencedor e 35%, ao derrotado. Os demais votos foram considerados não válidos por serem votos em branco ou nulos. É correto afirmar que o vencedor obteve, dos votos válidos, o percentual de","alternativas":["56,25%.","56,75%.","59,50%.","64,20%.","64,30%"],"correta":"A"},{"numero":20,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Probabilidade","enunciado":"Uma moeda honesta foi lançada 4 vezes seguidas e, em todos os lançamentos, o resultado foi cara. É correto concluir que, se essa moeda for lançada uma quinta vez, a probabilidade de que o resultado seja coroa é de","alternativas":["20%.","25%.","50%.","75%.","80%."],"correta":"C"},{"numero":21,"disciplina":"Informática","assunto":"Hardware e Periféricos","enunciado":"Numerosos dispositivos chamados de periféricos são conectados aos computadores. Os periféricos usados para inserir informações no sistema são classificados como periféricos de entrada. Assinale a opção que indica o periférico de entrada de dados.","alternativas":["Mouse.","Monitor.","Caixa de som.","Impressora 3D.","Fone de ouvido"],"correta":"A"},{"numero":22,"disciplina":"Informática","assunto":"Windows","enunciado":"Os atalhos de teclado são maneiras de otimizar o tempo para se realizar tarefas no computador. Considerando a versão do sistema operacional Windows 11, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Ctrl+ X é o atalho usado para deletar um arquivo. ( ) Ctrl + C é o atalho indicado para copiar um arquivo. ( ) Alt + Tab é o atalho apropriado para ligar o computador. As afirmativas são, respectivamente,","alternativas":["F – F – F.","V – F – F.","V – V – V.","F – V – F.","V – V – F"],"correta":"D"},{"numero":23,"disciplina":"Informática","assunto":"Software e Sistemas Operacionais","enunciado":"O sistema de arquivos do sistema operacional Windows 11 nomeia um arquivo por meio de duas partes. A primeira parte identifica o nome do arquivo e a segunda parte indica o tipo do arquivo mediante a extensão. Assinale a opção que indica a extensão mais usada para salvar um arquivo no programa Word.","alternativas":[".accdt",".docx",".mp4",".iso",".avi"],"correta":"B"},{"numero":24,"disciplina":"Informática","assunto":"Correio Eletrônico","enunciado":"O correio eletrônico é um serviço que permite enviar mensagens para qualquer destinatário em qualquer lugar do mundo de maneira rápida e de custo reduzido. Os endereços eletrônicos são únicos e seguem um formato característico. As mensagens ficam armazenadas nos servidores de um domínio e podem ser acessadas quando utilizamos os mecanismos apropriados. De acordo com o texto, analise os itens a seguir. I. O formato do endereço nome@dominio.com.br é um formato válido. II. É necessário que o remetente do cor reio eletrônico e o receptor da mensagem estejam com conexão ativa na internet durante todo o tempo. III. Por intermédio do serviço é possível enviar e receber tanto mensagens de texto como arquivos de vídeo. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":"C"},{"numero":25,"disciplina":"Informática","assunto":"Windows","enunciado":"No Windows versão 11, o recurso lixeira é um local de armazenamento temporário onde ficam depositados os arquivos antes de serem excluídos definitivamente dos discos rígidos de um computador. Sobre o recurso lixeira, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Para recuperar arquivo(s) excluido(s), o usuário deve abrir a pasta lixeira, selecionar o(s) arquivo(s) desejado(s), clicar no comando Restaurar este item na barra de comandos. ( ) Para excluir um item da lixeira o usuário deve utilizar o comando Ctrl+ S. ( ) Para excluir um arquivo diretamente do disco, sem que esse vá parar na lixeira, utiliza-se o comando Shift+Delete.","alternativas":["F – F – V.","V – V – V.","V – F – V.","F – F – F.","F – V – F"],"correta":"C"},{"numero":28,"disciplina":"Informática","assunto":"Hardware e Periféricos","enunciado":"A impressora é um dispositivo que permite imprimir diferentes tipos de documentos. Ela deve estar conectada ao computador de maneira física com cab o ou conectada por meio de uma conexão sem fio. Em todos os casos há um procedimento padrão para que haja a impressão. Levando em consideração o programa da Microsoft denominado de Word, analise os itens a seguir. I. Deve-se selecionar a opção de impressão no menu principal e selecionar a impressora que está conectada e imprimir. II. Deve-se usar a opção de transformar no menu principal. III. Pode se usar o atalho de teclado Ctrl+P para realizar a impressão rápida. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"C"},{"numero":29,"disciplina":"Informática","assunto":"Hardware e Periféricos","enunciado":"Atualmente existem no mercado diferentes tipos de dispositivos capazes de armazenar diferentes tipos de dados. Os dispositivos podem ser divididos em três categorias: discos rígidos magnéticos, discos do tipo flash memory e discos de mídias óticas. Assinale a opção que indica uma mídia ótica.","alternativas":["DVD.","Pen drive.","HD externo.","Fita magnética.","Cartão de memória"],"correta":"A"},{"numero":30,"disciplina":"Informática","assunto":"Redes de Computadores","enunciado":"Sobre a conexão à rede de computadores, que pode ser feita por diferentes métodos, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A conexão via satélite é uma forma de acesso em qualquer região do planeta, diretamente do satélite geoestacionário. ( ) A conexão via modem a cabo é uma forma de acesso por cabo modem, por meio de uma operadora de serviços de internet utilizando cabos físicos. ( ) A conexão de rádio é uma forma de acesso via transmissão de dados via antenas de rádio. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – V – V.","V – V – F.","V – F – V. Módulo II – Conhecimentos Específicos"],"correta":"B"},{"numero":31,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"A Constituição Federal de 1988 prevê que o Sistema Único de Saúde (SUS) seja estruturado com princípios e diretrizes específicas. Conforme determinado pel a Constituição, assinale a opção que indica a estratégia de organização dos serviços de saúde em níveis de complexidade crescente, com a finalidade de racionalizar o uso dos recursos.","alternativas":["Equidade.","Integralidade.","Hierarquização.","Descentralização.","Participação popular"],"correta":"C"},{"numero":32,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Assinale a opção que indica, segundo a Organização Mundial da Saúde, a denominação dos fatores econômicos e sociais relacionados com a produção do processo saúde -doença e o sistema de cuidados.","alternativas":["Ações de promoção de saúde.","Determinantes sociais da saúde.","Territórios e ambientes saudáveis.","Itens do parque industrial da saúde.","Articulações intersetoriais em saúde."],"correta":"B"},{"numero":33,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Analise a lista de doenças a seguir. I. Sarampo. II. Febre amarela. III. Tuberculose. IV. Esquistossomose. Assinale a opção que contém as doenças pertencentes à lista de agravos de notificação compulsória imediata ao Ministério da Saúde.","alternativas":["I e II, apenas.","I e III, apenas.","II e III, apenas.","II e IV, apenas.","III e IV, apenas"],"correta":"A"},{"numero":34,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"O Brasil enfrenta um surto de Oropouche, com mais de 8 mil casos confirmados esse ano, incluindo três mortes. Cerca de 44,5% dos casos ocorreram em estados da Região Norte. Sobre o tema, analise as afirmativas a seguir. I. O principal vetor no Brasil é o maruim (Culicoides paraensis). II. A letalidade do Oropouche é geralmente muito menor que a da dengue. III. O agente etiológico envolvido é o protozoário Myxobolus braziliensis. IV. Os quadros clínicos são facilmente diferenciados da dengue pela diferença no tempo de incubação. Está correto o que se afirma em","alternativas":["I e II, apenas.","I e III, apenas.","II e III, apenas.","II e IV, apenas.","III e IV, apenas"],"correta":"A"},{"numero":35,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Em função da importância do uso de ferramentas de aná lise espacial na investigação de epizootias, é imperativo padronizar as unidades de medida aferidas com aparelhos GPS ( Global Positioning System) nas seguintes coordenadas geográficas:","alternativas":["altitude e amplitude.","latitude e longitude.","longitude e altitude.","platitude e latitude.","amplitude e platitude"],"correta":"B"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"O município de Canaã dos Carajás tem como uma de suas principais atividades econômicas a mineração de ferro. A exposição continuada à poeira de minério do ferro pode causar a pneumoconiose denominada siderose. A respeito da siderose, analise as afirmativas a seguir. I. A maioria dos casos é assintomática. II. O uso de equipamentos de proteção individual diminui o risco dos trabalhadores de desenvolver a doença. III. As pessoas acometidas são elegíveis para receber a vacinação pneumocócica independentemente da idade. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"E"},{"numero":37,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A implementação do Regulamento Sanitário Internacional no Brasil permitiu a promoção de parcerias globais para o fortalecimento do Sistema Nacional de Vigilância em Saúde, com destaque para o aprimoramento da rede de Centros de Informações Estratégicas em Vigilância em Saúde (CIEVS). Sobre as competências da Rede CIEVS, analise as afirmativas a seguir. I. Verificar eventos e rumores de Saúde Pública que possam constituir ameaça à saúde da população. II. Coletar, consolidar, avaliar, analisar e disseminar informações referentes a eventos de Saúde Pública. III. Supervisionar o funcionamento das Coordenações e Postos de Vigilância Sanitária de Portos, Aeroportos e Fronteiras nos Estados.","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"B"},{"numero":38,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"O Levantamento Rápido de Índices para Aedes aegypti (LIRAa) constitui um método simplificado que proporciona uma rápida obtenção de indicadores entomológicos, permitindo uma compreensão abrangente da distribuição desse vetor. A respeito do LIRAa, assinale a afirmativa correta.","alternativas":["O Índice de Recipiente indica a porcentagem de larvas de A. aegypti em cada depósito positivo.","O Índice de Breteau indica a média do número de depósitos positivos para A. aegypti por cada imóvel pesquisado.","O LIRAa é a principal metodologia para avaliação de eficácia das medidas de controle vetorial ambiental em um município.","O Índice de Infestação Predial permite a classificação da situação de cada área pesquisada quanto ao risco de surto de dengue.","O LIRAa é realizado a partir de resultados positivos em armadilhas de oviposição realizados em visitas domiciliares de 100% dos imóveis."],"correta":"D"},{"numero":39,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"O Sistema de Vigilância de Epizootias em primatas não humanos (PNH) capta informações sobre adoecimento ou morte desses animais e investiga, adequadamente, esses eventos, com a finalidade de subsidiar a tomada de decisão para a adoção de medidas de prev enção e de controle e para reduzir a morbimortalidade da doença na população humana, em áreas afetadas. Sobre o tema, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A área de abrangência para a vigilância de epiz ootias em PNH compreende todo o território nacional. ( ) Com as coordenadas geográficas dos locais de investigação, é possível cruzar informações a respeito do clima, da cobertura vegetal e da hidrografia. ( ) A notificação da morte de PNH à unidade lo cal da Secretaria Municipal de Saúde pode ser realizada por qualquer indivíduo, o mais brevemente possível. As afirmativas são, respectivamente,","alternativas":["F – F – F.","F – V – F.","V – F – V.","V – V – V.","F – F – V"],"correta":"D"},{"numero":40,"disciplina":"Enfermagem","assunto":"Atenção Primária à Saúde","enunciado":"O e-SUS APS é uma estratégia criada para reestruturar as informações da Atenção Primária à Saúde (APS) em nível nacional, entendendo que a qualificação da gestão da informação é fundamental para ampliar a qualidade no atendimento à população. A respeito da estratégia e -SUS APS analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O sistema de processamento e a disponibilização de dados e informações relacionadas à APS é o Sistema de Informação em Saúde para a Atenção Básica (SISAB). ( ) O Sistema de Informação em Saúde para a Atenção Básica (SISAB) é alimentado pelo Sistema com Coleta de Dados Simplificada (CDS) e pelo Sistema com Prontuário Eletrônico do Cidadão (PEC). ( ) Os sistemas e -SUS Território, e-SUS Atividade Coletiva e e-SUS Vacinação alimentam o sistema e-SUS Gestão, que subsidia os gestores municipais com as informações das atividades realizadas pelas equipes de saúde da família. As afirmativas são, respectivamente,","alternativas":["F – F – F.","F – V – F.","V – F – V.","V – V – V.","V – V – F"],"correta":"E"},{"numero":41,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"A Atenção Básica e a Vigilância em Saúde deverão desenvolver ações integradas visando à promoção da saúde e à prevenção de doenças nos territórios sob sua responsabilidade. Sobre as atribuições da Vigilância na Atenção Básica, de acordo com as políticas definidas do SUS elencadas na Portaria de Consolidação no 2/2017, analise os itens a seguir. I. Vigilância de infecção hospitalar. II. Vigilância da violência e acidentes. III. Vigilância das doenças não transmissíveis. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"D"},{"numero":42,"disciplina":"Enfermagem","assunto":"Atenção Primária à Saúde","enunciado":"As visitas domiciliares são ações realizadas pelos profissionais de saúde, com o objetivo de monitorar, educar, prevenir e tratar condições de saúde em ambientes domiciliares. Sobre as atribuições dos técnicos em vigilância epidemiológica durante as visitas domiciliares, assinale a afirmativa correta.","alternativas":["Diagnosticar casos suspeitos de doenças de natureza neoplásica.","Prescrever medicamentos para prevenção de doenças transmissíveis.","Coletar dados e indicadores relacionados às doenças não transmissíveis.","Transportar pessoas com sintomas psiquiátricos para internação hospitalar.","Aplicar medicamentos por via intravenosa, evitando hospitalização desnecessária"],"correta":"C"},{"numero":43,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"A respeito do uso de larvicidas e inseticidas durante ações de controle de vetores em áreas residenciais, assinale a opção que descreve uma prática correta.","alternativas":["No Brasil, os inseticidas dispensam a aprovação e a liberação de órgãos de vigilância sanitária.","A aplicação de larvicidas deve ser realizada, preferencialmente, em locais secos e iluminados.","A vantagem dos larvicidas sobre os inseticidas é sua atuação em todas as fases de desenvolvimento dos insetos.","Em ambientes internos sem ventilação adequada deve -se preferir a aplicação de inseticidas com ação residual.","As dosagens recomendadas e as normas de segurança indicadas nas instruções de uso devem ser respeitadas."],"correta":"E"},{"numero":44,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"O plano de Ações Estratégicas para o Enfrentamento das Doenças Crônicas e Agravos Não Transmissíveis no Brasil (DANT) 2021-2030 apresenta-se como diretriz para a prevenção dos fatores de risco das DANT e para a promoção da saúde da população. Sobre esse plano, analise as afirmativas a seguir. I. O monitoramento da carga de mortalidade por DCNT atribuída à poluição do ar é realizado com informações produzidas por metodologia que combina dados de saúde e de qualidade do ar. II. Para o monitoramento das metas de redução da taxa de mortalidade prematura por DCNT, deve -se considerar os óbitos ocorridos em idades menores que 30 anos. III. Os óbitos por intoxicações exógenas por produtos de uso domiciliar, alimentos e por uso abusivo de álcool e outras drogas fazem parte do Eixo Vigilância em Saúde das DCNT. Está correto o que se afirma em","alternativas":["II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"C"},{"numero":45,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A Portaria MS/GM nº 1.356 iniciou a implantação do Sistema de Vigilância de Violências e Acidentes (VIVA) no Brasil. Sobre o VIVA, analise as afirmativas a seguir. I. O componente VIVA Inquérito realiza inquéritos periódicos em unidades sentinelas de urgência e emergência para descrever o perfil das vítimas de violências. II. O componente de Vigilância Contínua desse sistema integra o Sistema de Informação de Agravos de Notificação (SINAN). III. Os casos de tráfico de pessoas e trabalho escravo não são objeto de vigilância no VIVA. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"B"},{"numero":46,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Assinale a opção que apresenta a prática que, durante uma operação de campo no controle de doenças transmitidas por vetores, garante a segurança e sua efetividade.","alternativas":["Avaliar a necessidade de uso de EPIs dependendo do tempo de exposição de risco.","Encerrar a operação somente quando toda a quantidade dos produtos tiver sido aplicada.","Focar as áreas de difícil acesso em detrimento de áreas que apresentem menor infestação.","Usar produtos químicos sem consultar previamente os manuais e orientações específicas para cada tipo de intervenção.","Manter registros detalhados de cada atividade, como áreas cobertas, quantidade de produtos aplicados e observações importantes"],"correta":"E"},{"numero":47,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"O Sistema de Informação de Vigilância Epidemiológica da Malária (SIVEP-Malária) é usado no Brasil para monitorar e gerenciar os casos de malária em todo o território nacional. A respeito desse sistema, assinale a afirmativa correta.","alternativas":["Substitui a vigilânc ia de campo para controle vetorial se alimentado com dados suficientes.","Executa algoritmos que permitem a decisão automática durante as operações de campo.","Auxilia o diagnóstico da espécie de Plasmodium durante o atendimento em áreas remotas.","Possui um módulo de preenchimento pelo paciente, permitindo atendimento à distância.","Permite a análise de séries temporais de casos por diagnóstico da espécie de Plasmodium"],"correta":"E"},{"numero":48,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Entre as ações de controle de anofelinos vetores da malária está a Borrifação Residual Intradomiciliar (BRI). A respeito da estratégia de BRI, assinale a afirmativa correta.","alternativas":["A periodicidade das operações depende de orientações técnicas específicas para cada região e condições ambientais.","É considerada viável em localidades onde se possa atingir, no mínimo, 50% de cobertura das residências.","As paredes devem ser higienizadas com água e sabão após 24 horas da aplicação.","Deve ser priorizada em domicílios que possuam paredes incompletas ou danificadas.","Exige a permanência da família no interior do domicílio durante o procedimento"],"correta":"A"},{"numero":49,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Assinale a opção que apresenta, corretamente, uma ação de promoção da saúde.","alternativas":["Realizar campanhas sobre alimentação saudável.","Realizar inspeções em estabelecimentos de saúde.","Notificar casos de violência e lesões autoprovocadas.","Monitorar casos suspeitos de doenças transmissíveis.","Aplicar larvicidas em áreas próximas a coleções hídricas"],"correta":"A"},{"numero":50,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Segundo o volume 55, nº 15, do Boletim Epidemiológico, de 2024, o Estado do Pará registrou 11.206 casos de acidentes com animais peçonhentos em 2023, cerca de 16% dos casos notificados no país naquele ano. Os acidentes com animais peçonhentos registrados no Estado do Pará, envolveram, mais comumente,","alternativas":["aranhas.","abelhas.","lagartas.","serpentes.","escorpiões."],"correta":"D"}]},{"codigo":"canaa2025-san","ano":2025,"orgao":"Prefeitura de Canaã dos Carajás","cargo":"Agente de Serviços de Vigilância Sanitária","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/agente-de-servicos-de-vigilancia-sanitariacnm107-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/prefcanaa202403_gabarito_definitivo-compilado-06.04_0.pdf","questoes":[{"numero":32,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"O Padrão Microbiológico para a Vigilância Sanitária é o conjunto de critérios estabelecidos para a presença, ausência e limites aceitáveis de microrganismos em produtos ou ambientes, com o objetivo de proteger a saúde pública. A respeito do padrão microbiológico, de acordo com a Instrução Normativa nº 60/2019, analise as afirmativas a seguir. I. Os limites aceitáveis de microrganismos em um alimento são estabelecidos por regulamentações baseadas em evidências científicas. II. O alimento, o microrganismo, o ponto específico da cadeia em que esse padrão é aplicável, o limite microbiológico mínimo e o máximo, quando aplicáveis, e o plano de amostragem, são componentes do padrão microbiológico. III. A pesquisa de Enterobacteriaceae foi substituída pela pesquisa de coliformes fecais, seguindo padrões estabelecidos internacionalmente. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"B"},{"numero":34,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Amostras de sangue e urina coletadas na rotina das unidades básicas de saúde devem ser transportadas para laboratórios de análises seguindo normas de segurança, recebendo o código UN 3373, indicando Material Biológico da Categoria","alternativas":["A.","B.","C.","D.","E"],"correta":"B"},{"numero":35,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"O Certificado Internacional de Vacinação ou Profilaxia (CIVP) é o documento que comprova a vacinação de febre amarela. Ele é necessário porque alguns países exigem o documento para a entrada em seu território. Para situações excepcionais, o CIVP pode ser solicitado para","alternativas":["tuberculose e meningite.","tuberculose e hepatite A.","poliomielite e hepatite A.","poliomielite e meningite.","hepatite A e meningite"],"correta":"D"},{"numero":36,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Os agentes biológicos, que afetam o ser humano, os animais e as plantas, são distribuídos em classes de risco assim definidas: • Classe de risco 1 (baixo risco individual e para a comunidade); • Classe de risco 2 (moderado risco individual e limitado risco para a comunidade); • Classe de risco 3 (alto risco individual e moderado risco para a comunidade); • Classe de risco 4 (alto risco individual e para a comunidade). De acordo com a classificação adotada pela Comissão de Biossegurança em Saúde do Ministério da Saúde, os vírus SARS- CoV-2 e mpox são alocados, respectivamente, nas classes","alternativas":["2 e 2.","2 e 3.","3 e 3.","3 e 4.","4 e 4"],"correta":"C"},{"numero":37,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Leia o trecho a seguir. As Boas Práticas de Fabricação (BPF) abrangem um conjunto de medidas que devem ser adotadas pelas indústrias de alimentos e pelos serviços de alimentação para o correto manuseio de alimentos, abrangendo desde as matérias -primas até o produto final, de form a a garantir a segurança e integridade do consumidor. ANVISA, 2019. A respeito das BPF em estabelecimentos de alimentos, assinale a afirmativa correta.","alternativas":["É preciso definir uma sistemática de separação entre resíduos recicláveis e orgânicos.","Os equip amentos devem ser higienizados uma vez por mês com álcool etílico 70%.","O detergente recomendado para a limpeza dos alimentos é o quaternário de amônio.","Adornos como anéis e pulseiras devem ser encobertos por luvas pelos funcionários.","O uso de s ubstâncias químicas para o controle de pragas é contraindicado nesses estabelecimentos"],"correta":"A"},{"numero":38,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A cosmetovigilância é uma atividade complexa que requer a colaboração de diversos atores. O papel da vigilância local é fundamental para garantir a segurança dos con sumidores que utilizam produtos cosméticos. As opções a seguir apresentam atribuições da Vigilância Sanitária Local, à exceção de uma. Assinale-a.","alternativas":["Identificar e coletar amostras suspeitas para análise.","Fornecer informações sobre a legislação a comerciantes.","Isentar empresas de seguirem regulamentações federais.","Publicar alertas sobre cosméticos que apresentam riscos.","Registrar e acompanhar notificações de eventos adversos."],"correta":"C"},{"numero":39,"disciplina":"Enfermagem","assunto":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"O processo de destinação correta de embalagens vazias e resíduos de agrotóxicos é regulamentado pela Lei Federal nº 9.974/2000 e pelo Decreto nº 4.074/2002, que estabelecem responsabilidades de agricultores, comerciantes, fabricantes e do poder público. A respeito do descarte correto de embalagens vazias de agrotóxicos, de acordo com a legislação, assinale a afirmativa correta.","alternativas":["Até a devolução, as embalagens devem ser armazenadas em locais sem ventilação direta.","As sobras de calda dentro de embalag ens devem ser tratadas com cal antes do descarte.","As embalagens com as notas fiscais devem ser mantidas íntegras até a sua devolução.","As embalagens devem ser devolvidas em centrais de reciclagem comunitárias.","A limpeza das embalagens deve ser p or lavagem sob pressão ou processo de tríplice lavagem"],"correta":"E"},{"numero":40,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"A inspeção em estabelecimentos hospitalares é fundamental para garantir um ambiente seguro e de qualidade para os pacientes e trabalhadores, reduzindo riscos e promovendo a conformidade com as melhores práticas sanitárias. Sobre os procedimentos realizados durante a inspeção de estabelecimentos de saúde, analise as afirmativas a seguir. I. Em inspeções regulares não é possível emitir autos de infração. II. A inspeção inclui a verificação do armazenamento correto dos medicamentos, incluindo controle de temperatura. III. Deve-se conferir documentos que comprovam a capacitação dos profissionais e os treinamentos realizados. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"D"},{"numero":41,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"De acordo com a Resolução da Diretoria Colegiada, RDC nº 682 de 2022, que dispõe sobre produtos saneantes desinfetantes, assinale a afirmativa correta.","alternativas":["Aplicação residual refere-se à aplicação de um produto no ar, atingindo diretamente insetos voadores incômodos ou nocivos à saúde.","Agente fumigante é a substância que apresenta propriedade de volatilização quando submetido à ação do calor ou de outra fonte de energia.","Agente atraente é a substância destinada a repelir pragas, com baixa toxicidade e considerada de uso seguro, de acordo com as recomendações de uso.","Agente repelente é uma substância utilizada para atrair a praga alvo e induzi -la a ingerir a isca, en trar em contato com o princípio ativo ou facilitar sua captura.","Aplicação espacial refere-se à aplicação de um produto nos locais de trânsito de pragas, com formulações cujos ingredientes permaneçam ativos por período prolongado"],"correta":"B"},{"numero":42,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Assinale a opção qu e indica, corretamente, a composição da infraestrutura administrativa determinada para a Vigilância Sanitária na esfera municipal.","alternativas":["Plano de ação, equipamentos de proteção individual e kit inspeção.","Suporte laboratorial, equipamentos de proteção ind ividual e veículos.","Materiais educativos, procedimentos operacionais e kit inspeção.","Cadastro de estabelecimentos, plano de ação e sistemas de informação.","Sistemas de informação, suporte laboratorial e procedimentos operacionais"],"correta":"D"},{"numero":43,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"De acordo c om os conceitos de Boas Práticas para Serviços de Alimentação, a higienização de alimentos deve ser realizada de acordo com os seguintes processos, em ordem de realização.","alternativas":["Lavagem das mãos com sabonete antisséptico, seguida de redução, por método físic o e ou agente químico, do número de microrganismos.","Lavagem das mãos com sabonete antisséptico, seguida de lavagem ou cocção de alimentos para posterior embalagem, rotulagem e refrigeração.","Redução, por método físico e ou agente químico, do número de microrganismos, seguida de remoção de substâncias minerais e ou orgânicas indesejáveis.","Remoção de substâncias minerais e ou orgânicas por método físico e ou agente químico, seguida de lavagem ou cocção de alimentos para posterior refrigeração.","Remoção de substâncias minerais e ou orgânicas indesejáveis, seguida de redução, por método físico ou agente químico, do número de microrganismos"],"correta":"B"},{"numero":44,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"Assinale a opção que indica a função principal da Conferência de Saúde, instância colegiada de participação da comunidade na gestão do Sistema Único de Saúde.","alternativas":["Definir diretrizes gerais das políticas de saúde.","Emitir pareceres técnicos para auxiliar a Justiça.","Auditar processos abertos pela vigilância sanitária.","Promover ações de educação continuada na saúde.","Expor as experiências dos serviços de vigilância sanitária."],"correta":"A"},{"numero":45,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A apreensão de amostras pela Vigilância Sanitária é um ato necessário para a realização de análises laboratoriais e está prevista na Lei Federal nº 6.437/1977. A respeito da regulamentação da apreensão de amostras, analise as afirmativas a seguir. I. A apreensão de amostras para apuração de ilícito, em se tratando de produto de substância referidas no art. 10, será realizada mediante análise fiscal, e de interdição, se for o caso. II. A apreensão de amostras para efeito de análise, fiscal ou de controle, deve ser acompanhada da interdição do produto. III. A apreensão de amostras é dividida em 2 etapas para garantir a autenticidade e inviolabilidade dos resultado s: primeiro a amostra é encaminhada para o laboratório oficial e depois para ser periciada pela parte investigada. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"A"},{"numero":46,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"De acordo com a Lei nº 6.437/1977, as infrações sanitárias podem ser classificadas em leves, graves ou gravíssimas, de acordo com as consequências para a saúde pública e a presença de circunstâncias atenuantes ou agravantes. Conforme o estabelecido na referida lei, assinale a opção que apresenta duas circunstâncias agravantes.","alternativas":["A ação do infrator não ter sido fundamental para a consecução do evento e ser o infrator reincidente.","O infrator coagir outrem para a execução material da infração e procurar reparar as consequências da ação.","O infrator deixar de tomar as providências de sua alçada tendo conhecimento do ato e ser o infrator primário.","Ter o infrator sofrido coação para a prática do ato e ter cometido a infração para obter vantagem pecuniária.","Ser o infrator reincidente e ter o infrator cometido a infração para obter vantagem pecuniária"],"correta":"E"},{"numero":47,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"De acordo com a Resolução RDC nº 940/2024 – ANVISA, a monografia de Cannabis sativa foi incluída na 7ª edição da Farmacopeia Brasileira. Assinale a opção que indica o objetivo dessa medida.","alternativas":["Dispensar a comercialização de formulações farmacêuticas que contenham extrato de Cannabis sativa da aprovação pela ANVISA.","Estabelecer a do sagem de medicamentos que utilizam Cannabis sativa abaixo da qual não será mais obrigatório o aviamento de receitas.","Determinar o fluxo de plantio, colheita e processamento da planta para uso como matéria -prima na produção de medicamentos e cosméticos.","Dispensar da aprovação pela ANVISA a realização de pesquisas clínicas que envolvam produtos que contenham extrato de Cannabis sativa.","Estabelecer os padrões mínimos de qualidade e segurança para as inflorescências da planta, utilizadas como matéri a prima na produção de medicamentos"],"correta":"E"},{"numero":48,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A Nota Técnica nº 2/2024/SEI/GGTES/DIRE3/ANVISA, que presta esclarecimentos sobre os serviços de estética e atendimento às normas sanitárias aplicáveis, classifica estabelecimentos de estética e embelezamento como serviços de saúde ou como serviços de interesse à saúde. A respeito de tal diferenciação, assinale a afirmativa correta.","alternativas":["Os serviços de interesse à saúde devem ser realizados por profissionais da área da saúde de nível superior.","Os serviços de inter esse à saúde estão dispensados de apresentar procedimentos operacionais escritos.","Tanto os serviços de saúde como os de interesse à saúde não necessitam de supervisão por profissionais de saúde.","Tanto os serviços de saúde como os de interesse à saú de podem realizar administração de medicamentos injetáveis.","Tanto os serviços de saúde como os de interesse à saúde realizam atividades que podem alterar o estado de saúde do indivíduo"],"correta":"E"},{"numero":49,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Resolução da Diretoria Colegiada - RDC nº 699/2022 dispõe sobre regulamento técnico para produto saneante categorizado como alvejante à base de hipoclorito de sódio ou hipoclorito de cálcio. A respeito das normas para a rotulagem desses alvejantes, assinale a afirmativa correta.","alternativas":["Deve estar visível ao consumidor as instruções “Em caso de ingestão, provocar vômito” e “Não reutilizar a embalagem para outros fins”.","Está autorizado a exposição no rótulo de expressões como \"não tóxico\", \"seguro\", \"inócu o\", \"não prejudicial\" ou outras indicações similares.","A concentração de cloro ativo, expressa em % p/p ou o seu equivalente em g/L no momento do envase, deve estar indicada no painel principal do rótulo.","O texto do painel principal deve ser legível , indelével, no idioma do país em que será comercializado e posto em alto ou baixo relevo, junto ao nome do produto.","O prazo de validade será de 360 dias a partir da data de fabricação, exceto se for apresentado relatório de ensaio de estabilidade que comprove um prazo maior"],"correta":"C"}]}] as const;
export async function sincronizarFGVAbreuCanaaComplemento() {
 const usuario=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!usuario)return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const atuais=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const vistos=new Set(atuais.map(q=>norm(q.enunciado)));
 const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES) for(const q of lote.questoes){
   if(!q.enunciado.trim()||q.alternativas.length!==5||!["A","B","C","D","E"].includes(q.correta)||
      q.alternativas.some(x=>!x.trim())||new Set(q.alternativas.map(x=>x.trim().toLowerCase())).size!==5)
      throw new Error("[abreu-canaa-complemento] Questão inválida "+lote.codigo+" q"+q.numero);
   const origemId="fgv-"+lote.codigo+"-tipo1-q"+String(q.numero).padStart(2,"0");
   if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
   const hash=norm(q.enunciado);if(vistos.has(hash)){repetidas++;continue;}
   let disciplinaId=disciplinas.get(q.disciplina);
   if(!disciplinaId){
      let d=await prisma.disciplina.findFirst({where:{usuarioId:usuario.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
      if(!d)d=await prisma.disciplina.create({data:{usuarioId:usuario.id,nome:q.disciplina},select:{id:true}});
      disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
   }
   await prisma.questao.create({data:{
      usuarioId:usuario.id,disciplinaId,tema:q.assunto,fonte:FONTE_PROVAS_REAIS,origemId,
      enunciado:q.enunciado,dificuldade:"medio",banca:"FGV",ano:lote.ano,orgao:lote.orgao,cargo:lote.cargo,fonteUrl:lote.prova,
      explicacao:"FGV/"+lote.orgao+" "+lote.ano+", "+lote.cargo+", prova Tipo 1, questão "+q.numero+
        ". Gabarito definitivo: alternativa "+q.correta+". Caderno: "+lote.prova+" | Gabarito: "+lote.gabarito,
      alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
   }});
   inseridas++;vistos.add(hash);
 }
 console.log("[abreu-canaa-complemento] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" repetidas ignoradas.");
 return {inseridas,existentes,repetidas};
}
